// Общие помощники data-requests-reauth (#c3aa39). План: specs/data-requests-reauth.md.
// ЖЁСТКО: запрос на удаление НЕ отправляется, пароль НЕ вводится, «אישור» в окне не нажимается.
// Страховка — blockDataRequestWrites(): любые не-GET запросы к create_data_request / data_requests обрываются в браузере
// и записываются (тест проверяет, что их не было до пароля).
// Expo-роутер держит скрытые экраны в DOM — все локаторы только по видимым элементам.
import * as path from 'path';
import { Page, expect } from '@playwright/test';

export const PARENT_B = path.resolve(__dirname, '../../../auth/parent-b.json');

export const DATA_REQUEST_URL = '/privacy/data-request';
export const SUPPORT_EMAIL = 'support@benjico.ai';

/** Тексты формы (скрины .qa/screenshots/c3aa39-T1/T2/T5-*). */
export const T = {
  formTitle: 'בקשה לגבי נתוני ילד',
  whichChild: 'על איזה ילד?',
  kindView: 'לראות את המידע',
  kindDelete: 'למחוק מידע',
  kindFamily: 'למחוק את כל נתוני המשפחה',
  deleteChildHint: /נמחק את המידע גם מגיבויים ומספקים/,
  deleteFamilyHint: /בקשה למחוק את החשבון, את כל פרופילי הילדים/,
  detailsPlaceholder: 'מה חשוב שנדע?',
  send: 'שליחת הבקשה',
  reauthTitle: 'אימות זהות',
  reauthText: /כדי לשלוח בקשת מחיקה, הזינו שוב את סיסמת החשבון/,
  cancel: 'ביטול',
  sent: /הבקשה נשלחה|כבר יש בקשה כזו בטיפול/,
  settingsFamilyLink: 'מחיקת כל נתוני המשפחה',
};

/** Видимый текст с точным совпадением. */
export const visibleText = (page: Page, text: string | RegExp) =>
  page.getByText(text, { exact: true }).filter({ visible: true }).first();

/** Видимая кнопка/чип по тексту. */
export const visibleButton = (page: Page, name: string) =>
  page.getByRole('button', { name, exact: true }).filter({ visible: true }).first();

/** Чип выбора (ребёнок / действие). TODO verify selector: роль чипов (button / radio) при записи не проверялась — берём по видимому тексту. */
export const chip = (page: Page, text: string) => visibleText(page, text);

export interface BlockedWrite {
  method: string;
  url: string;
  body: unknown;
}

/** Оборвать в браузере любые записи запросов данных и вернуть список попыток. GET (список «הבקשות שלי») проходит. */
export async function blockDataRequestWrites(page: Page): Promise<BlockedWrite[]> {
  const blocked: BlockedWrite[] = [];
  await page.route(/\/rest\/v1\/(rpc\/create_data_request|data_requests)/, async (route) => {
    const req = route.request();
    if (['GET', 'HEAD', 'OPTIONS'].includes(req.method())) return route.continue();
    let body: unknown = req.postData();
    try {
      body = req.postDataJSON();
    } catch {
      /* не JSON */
    }
    blocked.push({ method: req.method(), url: req.url(), body });
    await route.abort('blockedbyclient');
  });
  return blocked;
}

/** Окно «אימות זהות» открыто: заголовок, текст про удаление, поле пароля, «ביטול». Пароль не вводим. */
export async function expectReauthDialog(page: Page) {
  await expect(visibleText(page, T.reauthTitle)).toBeVisible();
  await expect(page.getByText(T.reauthText).filter({ visible: true }).first()).toBeVisible();
  await expect(page.locator('input[type="password"]').filter({ visible: true })).toHaveCount(1);
  await expect(visibleButton(page, T.cancel).or(visibleText(page, T.cancel)).first()).toBeVisible();
}

/** «ביטול» в окне → окно закрыто. */
export async function cancelReauth(page: Page) {
  await visibleButton(page, T.cancel).or(visibleText(page, T.cancel)).first().click();
  await expect(page.getByText(T.reauthText).filter({ visible: true })).toHaveCount(0);
  await expect(page.locator('input[type="password"]').filter({ visible: true })).toHaveCount(0);
}

/** Кнопка «שליחת הבקשה» (не перепутать с текстом в списке). */
export const sendButton = (page: Page) => visibleButton(page, T.send).or(visibleText(page, T.send)).first();

/** Открыть форму и дождаться загрузки. */
export async function openForm(page: Page) {
  await page.goto(DATA_REQUEST_URL);
  await expect(visibleText(page, T.formTitle)).toBeVisible();
}
